// ThreadRelations provides type-safe names for Bun eager-loading.
// Use these instead of string literals in .Relation() calls to get compile-time safety.
//
//	q.Relation(ThreadRelations.BusinessUnit)
//	// Bun eager-loads the BusinessUnit association via a separate query
var ThreadRelations = struct {
	BusinessUnit string
	Organization string
	User         string
}{
	BusinessUnit: "BusinessUnit",
	Organization: "Organization",
	User:         "User",
}

// ThreadScopeTenant restricts a query to a single tenant by adding:
//
//	WHERE athr.organization_id = ? AND athr.business_unit_id = ?
//
// Returns the same *bun.SelectQuery so it can be chained fluently:
//
//	conversationcol.ThreadScopeTenant(sq, ti).
//		Where(conversationcol.ThreadColumns.ID.Eq(), id)
func ThreadScopeTenant(q *bun.SelectQuery, ti pagination.TenantInfo) *bun.SelectQuery {
	return buncolgen.ScopeTenant(q, ThreadColumns.OrganizationID, ThreadColumns.BusinessUnitID, ti)
}

// ThreadScopeTenantUpdate restricts an update query to a single tenant.
// Use this inside UpdateQuery.WhereGroup callbacks:
//
//	WhereGroup(" AND ", func(uq *bun.UpdateQuery) *bun.UpdateQuery {
//		return conversationcol.ThreadScopeTenantUpdate(uq, req.TenantInfo).
//			Where(conversationcol.ThreadColumns.ID.In(), bun.List(ids))
//	})
func ThreadScopeTenantUpdate(q *bun.UpdateQuery, ti pagination.TenantInfo) *bun.UpdateQuery {
	return buncolgen.ScopeTenantUpdate(q, ThreadColumns.OrganizationID, ThreadColumns.BusinessUnitID, ti)
}

// ThreadScopeTenantDelete restricts a delete query to a single tenant.
// Use this inside DeleteQuery.WhereGroup callbacks:
//
//	WhereGroup(" AND ", func(dq *bun.DeleteQuery) *bun.DeleteQuery {
//		return conversationcol.ThreadScopeTenantDelete(dq, req.TenantInfo).
//			Where(conversationcol.ThreadColumns.ID.Eq(), id)
//	})
func ThreadScopeTenantDelete(q *bun.DeleteQuery, ti pagination.TenantInfo) *bun.DeleteQuery {
	return buncolgen.ScopeTenantDelete(q, ThreadColumns.OrganizationID, ThreadColumns.BusinessUnitID, ti)
}

// ThreadApplyTenant returns a closure for SelectQuery.Apply() that scopes to a single tenant.
// Use this instead of wrapping ScopeTenant in an anonymous function:
//
//	q.Apply(conversationcol.ThreadApplyTenant(tenantInfo))
func ThreadApplyTenant(ti pagination.TenantInfo) func(*bun.SelectQuery) *bun.SelectQuery {
	return buncolgen.ApplyTenant(ThreadColumns.OrganizationID, ThreadColumns.BusinessUnitID, ti)
}

